import { readFile } from "node:fs/promises";
import { createBucket, list, get, put } from "@tigrisdata/storage";

async function main() {
  const trialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const srcBucket = `harbor-src-${trialId}`;
  const dstBucket = `harbor-dst-${trialId}`;

  console.log(`Source Bucket: ${srcBucket}`);
  console.log(`Destination Bucket: ${dstBucket}`);

  // 1. Create destination bucket
  const { error: createError } = await createBucket(dstBucket);
  if (createError && createError.message !== "Bucket already exists") {
    console.error(`Error creating bucket: ${createError.message}`);
    process.exit(1);
  }
  console.log(`Destination bucket ${dstBucket} created or already exists.`);

  // 2. List objects in source bucket
  const { data: objects, error: listError } = await list({
    prefix: "data/",
    config: { bucket: srcBucket },
  });

  if (listError) {
    console.error(`Error listing objects: ${listError.message}`);
    process.exit(1);
  }

  if (!objects) {
    console.log("No objects found in source bucket.");
    return;
  }

  console.log(`Found ${objects.length} objects to copy.`);

  // 3. Copy each object
  for (const obj of objects) {
    const { name } = obj;
    console.log(`Copying ${name}...`);

    const { data: body, error: getError } = await get(name, "string", {
      config: { bucket: srcBucket },
    });

    if (getError) {
      console.error(`Error getting object ${name}: ${getError.message}`);
      process.exit(1);
    }

    const { error: putError } = await put(name, body as string, {
      config: { bucket: dstBucket },
    });

    if (putError) {
      console.error(`Error putting object ${name}: ${putError.message}`);
      process.exit(1);
    }
  }

  console.log("Successfully copied all objects.");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

