  const rawTrialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const trialId = rawTrialId.replace(/_/g, "-");
  const srcBucket = `harbor-src-${trialId}`;

  console.log(`Trying Source Bucket: ${srcBucket}`);

  const { data, error } = await list({
    prefix: "data/",
    config: { bucket: srcBucket },
  });

  if (error) {
    console.error(`Error: ${error.message}`);
  } else {
    console.log(`Success! Found ${data?.length} objects.`);
  }
}

main();

