import { listBuckets } from "@tigrisdata/storage";

async function main() {
  const { data, error } = await listBuckets();
  if (error) {
    console.error(error.message);
  } else {
    const srcBuckets = data?.buckets.filter(b => b.name.startsWith('harbor-src'));
    console.log(srcBuckets);
  }
}

main();

import { listBuckets } from "@tigrisdata/storage";

async function main() {
  const { data, error } = await listBuckets();
  if (error) {
    console.error(error.message);
  } else {
    const matched = data?.buckets.filter(b => b.name.toLowerCase().includes('9zj'));
    console.log(matched);
  }
}

main();

import { listBuckets } from "@tigrisdata/storage";

async function main() {
  const { data, error } = await listBuckets();
  if (error) {
    console.error(error.message);
  } else {
    data?.buckets.map(b => b.name).sort().forEach(name => console.log(name));
  }
}

main();

import { listBuckets, list } from "@tigrisdata/storage";

async function main() {
  const { data: bucketsData, error: bucketsError } = await listBuckets();
  if (bucketsError) {
    console.error(bucketsError.message);
    return;
  }

  for (const bucket of bucketsData!.buckets) {
    const { data, error } = await list({
      prefix: "data/",
      config: { bucket: bucket.name },
    });
    if (!error && data && data.length > 0) {
      console.log(`Bucket ${bucket.name} has ${data.length} objects under data/`);
      for (const obj of data) {
        console.log(` - ${obj.name}`);
      }
    }
  }
}

main();

