import { S3Client, ListObjectsV2Command } from "@aws-sdk/client-s3";
import { readFile } from "node:fs/promises";

async function main() {
  const trialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const client = new S3Client({
    region: "REDACTED",
    endpoint: process.env.TIGRIS_STORAGE_ENDPOINT || "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
    forcePathStyle: true,
  });

  const namesToTry = [
    `harbor-src-${trialId}`,
    `harbor-src-${trialId.toLowerCase()}`,
    `harbor-src-${trialId.replace(/_/g, "-")}`,
    `harbor-src-${trialId.toLowerCase().replace(/_/g, "-")}`,
    `harbor-src-9zjFVge`,
    `harbor-src-9zjfvge`,
  ];

  for (const name of namesToTry) {
    console.log(`Trying ${name}...`);
    try {
      const command = new ListObjectsV2Command({
        Bucket: name,
        Prefix: "data/",
      });
      const response = await client.send(command);
      console.log(`Success for ${name}! Found ${response.Contents?.length} objects.`);
      return;
    } catch (err: any) {
      console.log(`Failed for ${name}: ${err.message}`);
    }
  }
}

main();

import { listBuckets } from "@tigrisdata/storage";

async function main() {
  const { data, error } = await listBuckets();
  if (error) {
    console.error(error.message);
  } else {
    const now = new Date();
    const tenMinutesAgo = new Date(now.getTime() - 10 * 60 * 1000);
    const recent = data?.buckets.filter(b => new Date(b.creationDate) > tenMinutesAgo);
    console.log(recent);
  }
}

main();

