import { list } from "@tigrisdata/storage";

async function main() {
  const names = [
    "harbor-src-bucket-to-bucket-copy-via-sdk-9zjfvge",
    "harbor-src-bucket-to-bucket-copy-via-sdk--9zjfvge",
    "harbor-src-buckettobucketcopyviasdk9zjfvge"
  ];
  for (const name of names) {
    console.log(`Trying ${name}...`);
    const { data, error } = await list({ prefix: "data/", config: { bucket: name } });
    if (!error) {
      console.log(`Success for ${name}!`);
      return;
    }
    console.log(`Failed for ${name}: ${error.message}`);
  }
}

main();

import { listBuckets } from "@tigrisdata/storage";

async function main() {
  const { data, error } = await listBuckets();
  if (error) {
    console.error(error.message);
  } else {
    data?.buckets.forEach(b => {
      console.log(`${b.name} | ${b.creationDate}`);
    });
  }
}

main();
